#include <iostream>
#include <cstring>
using namespace std;

int main() {
    // 遍历第一个三位数的可能范围：123到329
    for (int i = 123; i <= 329; ++i) {
        bool used[10] = {false}; // 标记数字1-9是否使用过
        int j = i * 2;
        int k = i * 3;
        // 分别检查i, j, k的每一位数字
        int num = i;
        for (int m = 0; m < 3; ++m) {
            used[num % 10] = true;
            num /= 10;
        }
        num = j;
        for (int m = 0; m < 3; ++m) {
            used[num % 10] = true;
            num /= 10;
        }
        num = k;
        for (int m = 0; m < 3; ++m) {
            used[num % 10] = true;
            num /= 10;
        }
        // 检查是否1-9都使用过且没有使用0
        bool valid = true;
        for (int d = 1; d <= 9; ++d) {
            if (!used[d]) {
                valid = false;
                break;
            }
        }
        if (valid) {
            cout << i << " " << j << " " << k << endl;
        }
    }
    return 0;
}
